package algorithms.strings;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class StringUtils {
public static boolean isBalanced(String s){Deque<Character> st=new ArrayDeque<>();for(char c:s.toCharArray()){if("([{ ".indexOf(c)>=0&&c!=' ')st.push(c);else {int i=")] }".replace(" ","").indexOf(c);if(i>=0&&(st.isEmpty()||st.pop()!="([{ ".charAt(i)))return false;}}return st.isEmpty();}public static boolean isPalindrome(String s){s=s.toLowerCase(Locale.ROOT).replaceAll("[^\\p{L}\\p{N}]","");for(int i=0,j=s.length()-1;i<j;i++,j--)if(s.charAt(i)!=s.charAt(j))return false;return true;}public static boolean isAnagram(String a,String b){if(a.length()!=b.length())return false;Map<Integer,Integer> c=new HashMap<>();a.codePoints().forEach(x->c.merge(x,1,Integer::sum));for(int x:b.codePoints().toArray()){int n=c.getOrDefault(x,0);if(n==0)return false;c.put(x,n-1);}return true;}public static List<List<String>> groupAnagrams(List<String> words){Map<String,List<String>> g=new LinkedHashMap<>();for(String w:words){List<Integer> chars=new ArrayList<>();w.codePoints().forEach(chars::add);String key=algorithms.sorting.MergeSort.mergeSort(chars).toString();g.computeIfAbsent(key,k->new ArrayList<>()).add(w);}return new ArrayList<>(g.values());}public static String runLengthEncode(String s){StringBuilder o=new StringBuilder();for(int i=0;i<s.length();){int j=i+1;while(j<s.length()&&s.charAt(j)==s.charAt(i))j++;o.append(j-i).append(s.charAt(i));i=j;}return o.toString();}public static String runLengthDecode(String s){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(\\d+)(.)",java.util.regex.Pattern.DOTALL).matcher(s);StringBuilder o=new StringBuilder();int end=0;while(m.find()){o.append(s,end,m.start()).append(m.group(2).repeat(Integer.parseInt(m.group(1))));end=m.end();}return o.append(s.substring(end)).toString();}public static String reverseWords(String s){List<String> w=new ArrayList<>(Arrays.asList(s.trim().split("\\s+")));Collections.reverse(w);return String.join(" ",w);}
}
